create table if not exists public.engr_ero_lecture_presentations (
  lesson_id uuid primary key references public.module_slides(id) on delete cascade,
  title text not null,
  html_content text not null,
  updated_at timestamptz not null default now()
);
alter table public.engr_ero_lecture_presentations enable row level security;
revoke all on table public.engr_ero_lecture_presentations from anon, authenticated;
grant all on table public.engr_ero_lecture_presentations to service_role;

insert into public.engr_ero_lecture_presentations (lesson_id, title, html_content)
values (
  'a2cdfbb4-566b-42ce-bc04-e15df9b602f9',
  'History of the Automobile and Fundamental Vehicle Systems',
  $engr_ero_html$
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>History of the Automobile | Engr Ero Learning Centre</title>
<style>
:root{--navy:#0b1f3a;--navy2:#13335f;--navy3:#0f2a4e;--orange:#ff7a1a;--blue:#4c9bff;--amber:#f2b01e;--ink:#eaf1fb;--mute:#9db3d1}
*{box-sizing:border-box;margin:0;padding:0}
html,body{height:100%;background:#050d19;color:var(--ink);font-family:system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif}
#app{min-height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;padding:8px}
.stage{container-type:size;position:relative;aspect-ratio:16/9;width:min(100vw - 16px,calc((100vh - 118px)*16/9));overflow:hidden;border-radius:10px;background:linear-gradient(135deg,#0b1f3a 0%,#102c52 55%,#0b1f3a 100%);box-shadow:0 10px 40px rgba(0,0,0,.5)}
.bg{position:absolute;inset:0;background-image:linear-gradient(rgba(76,155,255,.06) 1px,transparent 1px),linear-gradient(90deg,rgba(76,155,255,.06) 1px,transparent 1px);background-size:3cqw 3cqw;animation:drift 24s linear infinite}
@keyframes drift{to{background-position:6cqw 6cqw}}
.brand{position:absolute;top:2.2cqw;right:3cqw;font-size:1.05cqw;letter-spacing:.22em;color:var(--mute);font-weight:600}
.head{position:absolute;left:4cqw;top:2.6cqw;right:30cqw}
.head .chip{display:inline-block;font-size:1.05cqw;letter-spacing:.14em;text-transform:uppercase;color:var(--orange);font-weight:700;margin-bottom:.5cqw}
.head h1{font-size:3.1cqw;line-height:1.1;font-weight:700;letter-spacing:-.01em}
.visual{position:absolute;left:37cqw;right:4cqw;top:11.5cqw;height:33cqw;border-radius:1.2cqw;background:rgba(7,18,36,.55);border:1px solid rgba(76,155,255,.25);overflow:hidden}
.visual img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;display:none}
.visual.hasimg img{display:block;animation:kb 40s ease-in-out infinite alternate}
.visual.hasimg #viz{display:none}
@keyframes kb{from{transform:scale(1)}to{transform:scale(1.12)}}
#viz{position:absolute;inset:0}
#viz svg{width:100%;height:100%;display:block}
.onscreen{position:absolute;left:4cqw;top:14cqw;width:30cqw;display:flex;flex-direction:column;gap:1cqw}
.onscreen .c{font-size:1.45cqw;line-height:1.3;padding:.9cqw 1.1cqw;border-left:.35cqw solid var(--orange);background:rgba(19,51,95,.75);border-radius:.6cqw;opacity:0;transform:translateX(-1.2cqw);transition:opacity .5s,transform .5s}
.onscreen .c.on{opacity:1;transform:none}
.stage.cards .onscreen{left:4cqw;right:4cqw;top:12.5cqw;width:auto;display:grid;grid-template-columns:repeat(2,1fr);gap:1.6cqw}
.stage.cards .onscreen .c{font-size:2.3cqw;padding:2cqw 2.2cqw;border-left-width:.5cqw;display:flex;align-items:center;min-height:9cqw}
.stage.cards .visual{display:none}
.caption{position:absolute;left:5cqw;right:5cqw;bottom:2cqw;min-height:5.6cqw;display:flex;align-items:center;justify-content:center;text-align:center;font-size:1.7cqw;line-height:1.3;padding:.7cqw 2cqw;background:rgba(5,13,25,.72);border-radius:.8cqw;transition:opacity .25s}
.caption.off{opacity:0}
.think{position:absolute;right:4cqw;bottom:9.5cqw;font-size:1.5cqw;background:var(--amber);color:#1a1200;padding:.6cqw 1.4cqw;border-radius:99cqw;font-weight:700;opacity:0;transition:opacity .3s}
.think.on{opacity:1}
.seccard{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;background:linear-gradient(135deg,#0b1f3a,#16427a);opacity:0;pointer-events:none;transition:opacity .5s;text-align:center;gap:1cqw}
.seccard.on{opacity:1}
.seccard small{font-size:1.5cqw;letter-spacing:.3em;color:var(--orange);font-weight:700}
.seccard b{font-size:5cqw;max-width:80cqw;line-height:1.1}
.startcard{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;background:rgba(5,13,25,.88);gap:1.2cqw;text-align:center;cursor:pointer;z-index:5}
.startcard small{font-size:1.4cqw;letter-spacing:.3em;color:var(--orange);font-weight:700}
.startcard h2{font-size:4.2cqw;max-width:80cqw;line-height:1.1}
.startcard p{font-size:1.6cqw;color:var(--mute)}
.startcard .go{margin-top:1.4cqw;font-size:2cqw;background:var(--orange);color:#1b0b00;padding:1cqw 3cqw;border-radius:99cqw;font-weight:800}
.bar{width:min(100vw - 16px,calc((100vh - 118px)*16/9));display:flex;flex-direction:column;gap:8px}
.seek{position:relative;height:22px;cursor:pointer}
.seek .track{position:absolute;left:0;right:0;top:9px;height:5px;background:#1b3558;border-radius:5px}
.seek .fill{position:absolute;left:0;top:9px;height:5px;background:var(--orange);border-radius:5px;width:0}
.seek .tick{position:absolute;top:5px;width:2px;height:13px;background:#6f8fb8}
.seek .knob{position:absolute;top:4px;width:14px;height:14px;border-radius:50%;background:#fff;margin-left:-7px;left:0}
.ctl{display:flex;flex-wrap:wrap;gap:8px;align-items:center;font-size:14px}
.ctl button,.ctl select{background:#12305a;color:var(--ink);border:1px solid #2a5088;border-radius:8px;padding:7px 12px;font-size:14px;cursor:pointer}
.ctl button:hover,.ctl select:hover{background:#1a427a}
.ctl button.on{background:var(--orange);color:#1b0b00;border-color:var(--orange);font-weight:700}
.ctl .time{font-variant-numeric:tabular-nums;color:var(--mute);margin-left:auto}
</style>
</head>
<body>
<div id="app">
 <div class="stage" id="stage">
  <div class="bg"></div>
  <div class="brand">ENGR ERO LEARNING CENTRE</div>
  <div class="head"><div class="chip" id="secChip"></div><h1 id="title"></h1></div>
  <div class="visual" id="visual"><img id="img" alt=""><div id="viz"></div></div>
  <div class="onscreen" id="onscreen"></div>
  <div class="think" id="think">Pause and think</div>
  <div class="caption" id="caption"></div>
  <div class="seccard" id="seccard"></div>
  <div class="startcard" id="startcard">
    <small>ENGR ERO LEARNING CENTRE</small>
    <h2>History of the Automobile and Fundamental Vehicle Systems</h2>
    <p>70-minute university lecture for undergraduate engineering students</p>
    <div class="go">&#9654; Start lecture</div>
  </div>
 </div>
 <div class="bar">
  <div class="seek" id="seek"><div class="track"></div><div class="fill" id="pfill"></div><div class="knob" id="knob"></div></div>
  <div class="ctl">
    <button id="bPlay">&#9654; Play</button>
    <button id="bPrev" title="Previous scene">&#9198;</button>
    <button id="bBack" title="Back 10 s">-10s</button>
    <button id="bFwd" title="Forward 10 s">+10s</button>
    <button id="bNext" title="Next scene">&#9197;</button>
    <select id="selSpeed" title="Speed"><option value="0.5">0.5x</option><option value="1" selected>1x</option><option value="1.5">1.5x</option><option value="2">2x</option><option value="4">4x</option><option value="10">10x (preview)</option></select>
    <select id="selChap" title="Chapters"></select>
    <button id="bVoice" class="on" title="Browser voice-over narration">Voice: on</button>
    <button id="bCap" class="on">Captions</button>
    <button id="bFull">Fullscreen</button>
    <span class="time" id="time">00:00 / 70:00</span>
  </div>
 </div>
</div>
<script>
const SCENES = [{"n": 1, "title": "Welcome and the Meaning of an Automobile", "start": 0, "end": 100, "on": "ENGR ERO LEARNING CENTRE | History of the Automobile and Fundamental Vehicle Systems | Lecture 1 | Definition: Automobile = self-propelled road vehicle", "narr": "Good day, students, and welcome to the Engr Ero Learning Centre. In this lecture we will study the history of the automobile and the fundamental systems that make a vehicle work. By the end of seventy minutes, you should be able to look at any car on a Nigerian road, from a Toyota Corolla in Enugu to a danfo bus in Lagos, and explain how its engine, transmission, steering, suspension, brakes and electrical system cooperate to move it safely. Let us begin with a definition. The word automobile comes from two parts: auto, meaning self, and mobile, meaning moving. An automobile is a self-propelled vehicle that runs on roads, carries passengers or goods, and carries its own source of power. Notice that last point. A train taking power from overhead wires is not usually called an automobile, but a car carrying its own engine or battery is. A closely related term is motor vehicle. In most laws, including road traffic regulations in Nigeria, a motor vehicle is any mechanically propelled vehicle intended for use on public roads. So every automobile is a motor vehicle, but the legal term also includes motorcycles, tricycles and heavy trucks. Here is your first thinking question. Why do you think engineers insist that the vehicle carries its own power source? Keep that question in mind, because the answer explains the entire history we are about to study.", "pause": 2}, {"n": 2, "title": "Evolution of Transport and Why Automobiles Matter", "start": 100, "end": 200, "on": "Walking → Animals → Wheel and cart → Sail and rail → Automobile | Roles: mobility, trade, jobs, emergency services", "narr": "Human transportation did not begin with engines. For thousands of years people walked, carried loads on their heads, and later used animals such as horses, camels and donkeys. The invention of the wheel, usually dated to around three and a half thousand years before Christ in Mesopotamia and surrounding regions, allowed carts and chariots. Ships carried goods across seas, and in the nineteenth century steam railways transformed long-distance movement. But rails only go where tracks are laid, and horses tire, need feeding and leave waste in the streets. People wanted personal, flexible, mechanical transport. The automobile answered that need. Why does the automobile matter so much today? First, mobility. A family can travel to work, school or hospital on its own schedule. Second, trade. In Nigeria, the majority of goods, from yam in Benue to cement in Ogun, move by road. Third, employment. Mechanics, spare-parts traders in Nnewi, drivers, vulcanizers, panel beaters and manufacturers all depend on vehicles. Fourth, emergency services. An ambulance or fire truck is an automobile that saves lives. However, the automobile also brings challenges, including road accidents, air pollution and traffic congestion. As engineers, our job is not only to build vehicles, but to build them safer, cleaner and more efficient.", "pause": 2}, {"n": 3, "title": "Classification of Automobiles", "start": 200, "end": 300, "on": "Passenger | Commercial | Special-purpose | Examples", "narr": "Automobiles are classified in several ways, but the most common classification is by purpose. The first group is passenger vehicles. These are designed mainly to carry people, usually up to nine seats including the driver. Examples are saloon cars, hatchbacks, sport utility vehicles, station wagons and minibuses used privately. Their design priorities are comfort, safety, fuel economy and cost. The second group is commercial vehicles. These are designed to carry goods or large numbers of passengers for business. They include pickup trucks, panel vans, rigid trucks, articulated trucks and buses. Their design priorities are load capacity, durability, reliability and low cost per kilometre. A truck on the Lagos to Kano corridor may run several hundred thousand kilometres, so its engine and chassis must be much stronger than those of a small private car. The third group is special-purpose vehicles. These are built for a specific job rather than general transport. Examples are ambulances, fire engines, tow trucks, cement mixers, tankers, crane trucks, military vehicles and agricultural tractors. Often the chassis comes from a standard truck, and a special body is fitted by a body builder. Later we will also classify cars by fuel, engine position and drive layout. For now, remember this simple rule: passenger vehicles move people, commercial vehicles move business, and special-purpose vehicles perform a specialised task.", "pause": 2}, {"n": 4, "title": "Early Transport and the Steam Road Vehicle", "start": 300, "end": 420, "on": "Steam power: Newcomen (1712) → Watt (1760s to 1780s) → Road steam vehicles", "narr": "To understand the automobile, we must first understand why a new source of power was needed. Before the eighteenth century, the power available to transport was muscle: human or animal. The key breakthrough was the steam engine. Thomas Newcomen built a practical atmospheric steam engine in 1712, mainly for pumping water from mines. Later, James Watt improved the design in the 1760s and 1770s by adding a separate condenser, greatly improving efficiency. These engines were large, fixed and heavy. The next challenge was to make an engine light enough to move itself. A steam engine works by heating water in a boiler to make high-pressure steam. The steam pushes a piston in a cylinder, and the piston movement is converted by linkages into rotation. This is called external combustion, because the fuel burns outside the cylinder, in a furnace under the boiler. External combustion engines are powerful but heavy, slow to start, and need time to build up steam pressure. Even with these limitations, inventors began to ask a bold question: could steam power move a carriage? Several engineers tried. In the early 1800s, Richard Trevithick in Britain built steam road carriages, including one famously demonstrated in 1801 at Camborne in Cornwall, often called the Puffing Devil. These machines were important experiments, but they were noisy, difficult to steer and required constant attention.", "pause": 2}, {"n": 5, "title": "Nicolas-Joseph Cugnot and the First Steam Road Vehicle", "start": 420, "end": 540, "on": "Cugnot, France, 1769 (first model) | 1770 to 1771 (larger fardier) | Speed: about 4 km/h", "narr": "Now to a famous name: Nicolas-Joseph Cugnot, a French military engineer. In 1769 he built a small steam-powered vehicle, and around 1770 and 1771 he built a larger one, known as the fardier à vapeur, meaning steam dray. It was designed to haul heavy artillery for the French army. Many historians regard the larger machine as the first full-size self-propelled road vehicle, so it is often described as the first automobile in the broad sense of the word. The design was a three-wheeled tractor with the boiler hanging in front of the single front wheel, and two cylinders driving that wheel directly. Its top speed was only about four kilometres per hour, a walking pace. Steam pressure ran out quickly, so the vehicle had to stop every ten to fifteen minutes to rebuild pressure. Because the heavy boiler sat over the front wheel, steering was very difficult. A popular story says that Cugnot's vehicle crashed into a wall in Paris, which would make it the first road accident. Historians say the story is uncertain and the evidence is limited, so we should treat it as a tradition rather than proven fact. What is certain is that Cugnot's vehicle survives today in a museum in Paris, the Conservatoire national des arts et métiers. Here we see a very important lesson. Cugnot's machine proved the concept, but it was not practical. As engineers we separate three ideas: invention, which is a new concept; development, which is improvement until it works well; and commercial production, which is making it available to customers. Cugnot belongs to the invention stage.", "pause": 2}, {"n": 6, "title": "The Internal Combustion Engine Emerges", "start": 540, "end": 660, "on": "Lenoir 1860 | Otto 1876 (four-stroke) | Diesel: patent 1892, first working engine 1897", "narr": "Steam vehicles struggled because of weight and complexity. The solution was to burn the fuel inside the cylinder itself. This is called internal combustion. The fuel and air mixture explodes in the cylinder, and the expanding gases push the piston directly. There is no boiler, no large furnace and no waiting for steam pressure. Several engineers contributed. In 1860, Étienne Lenoir of Belgium and France produced a commercially used gas engine, but it was inefficient. In 1876, Nikolaus Otto in Germany developed the four-stroke engine, with the intake, compression, power and exhaust sequence that we still use in petrol engines today. We call the cycle the Otto cycle in his honour. A French engineer, Alphonse Beau de Rochas, had described the four-stroke principle earlier, in 1862, but Otto built the first successful engine using it. Another giant is Rudolf Diesel. He patented his compression-ignition engine concept in 1892 and produced a working engine in 1897. In a diesel engine the air is compressed so strongly that it becomes hot enough to ignite the fuel when injected, so no spark plug is needed. Notice the pattern: these engineers created the power unit. The remaining step was to place it in a carriage and make it practical for road use.", "pause": 2}, {"n": 7, "title": "Karl Benz, Daimler and Maybach", "start": 660, "end": 780, "on": "Benz Patent-Motorwagen: built 1885, patent filed 29 January 1886 | Daimler & Maybach: 1885 to 1889 | Bertha Benz 1888", "narr": "Now we meet the two names most associated with the birth of the practical automobile. Karl Benz, working in Mannheim, Germany, built a three-wheeled vehicle powered by his own single-cylinder four-stroke petrol engine. It was completed in 1885, and he filed for the patent on the twenty-ninth of January 1886, patent number 37435. That is why you will see both 1885 and 1886 in textbooks. The vehicle is known as the Benz Patent-Motorwagen, and it is widely recognised as the first purpose-built automobile powered by an internal combustion engine. The engine produced less than one horsepower. It had electric ignition, a water-evaporation cooling system and a simple belt drive. In August 1888, Bertha Benz, Karl's wife, made the first long-distance journey of about one hundred kilometres from Mannheim to Pforzheim with her sons, without telling her husband. She bought fuel from a pharmacy, cleaned a blocked fuel line with her hat pin and used her garter as insulation. Her trip proved the vehicle was practical, and it gave Benz valuable ideas, including adding extra gears for hills and brake linings. At the same time, Gottlieb Daimler and his colleague Wilhelm Maybach, working separately about one hundred kilometres away in Stuttgart, developed a light high-speed petrol engine. In 1885 it powered a wooden two-wheeled machine, often called the Reitwagen, and in 1886 a motorised four-wheeled carriage. Maybach also designed the spray-nozzle carburettor in the 1890s, and in 1901 the Mercedes 35 horsepower, one of the first modern-looking cars. Daimler and Benz would later merge, in 1926, creating Daimler-Benz.", "pause": 2}, {"n": 8, "title": "Henry Ford and Mass Production", "start": 780, "end": 900, "on": "Ford Model T 1908 | Moving assembly line 1913 | Price fell from US$850 (1908) toward US$300 (1920s)", "narr": "In the early years, automobiles were expensive, hand-built and available only to the rich. Henry Ford of the United States changed that. Ford did not invent the automobile, and he did not invent the assembly line. Ransom Olds had used a stationary assembly system in 1901. Ford's achievement was to combine standardised interchangeable parts, a simple durable design, and a continuously moving assembly line, then make a car ordinary families could afford. The car was the Ford Model T, launched in 1908. It had a four-cylinder engine of about twenty horsepower, a simple planetary two-speed gearbox with reverse, and high ground clearance for rough roads. In 1913 at Highland Park, Michigan, Ford introduced the moving assembly line for production. Instead of workers walking to a stationary car, the car moved past workers who each performed one task. The time to assemble a chassis fell dramatically, from about twelve and a half hours to about ninety-three minutes in the following year, according to commonly cited figures. As production efficiency rose, the price dropped. The Model T originally cost around eight hundred and fifty dollars, and prices fell below three hundred dollars in the mid-1920s. In 1914 Ford also introduced a wage of five dollars per day, which reduced worker turnover. By 1927, about fifteen million Model Ts had been built. For Nigerian engineering students there is a lesson. Manufacturing is not only about design; it is about process, cost and scale.", "pause": 2}, {"n": 9, "title": "Electric, Hybrid and Early Alternatives", "start": 900, "end": 1020, "on": "Early EVs c.1880s to 1900s | Lohner-Porsche hybrid 1900 | Toyota Prius 1997", "narr": "Many students are surprised to learn that electric cars are not new. Practical electric vehicles appeared in the 1880s, and around 1900 electric cars were popular in cities. They were quiet, clean and easy to start. At that time, petrol cars had to be hand-cranked, which was difficult and sometimes dangerous. In 1899, the electric car La Jamais Contente, driven by Camille Jenatzy, became the first road vehicle to exceed one hundred kilometres per hour. So why did electric cars fade? Batteries were heavy, expensive and offered limited range, while petrol was cheap and energy-dense. The electric self-starter, introduced by Charles Kettering of Cadillac in 1912, removed the hand crank, and Ford's mass production made petrol cars much cheaper. By the 1920s the petrol car dominated. Hybrid ideas are also old. Ferdinand Porsche developed the Lohner-Porsche mixed-drive vehicle around 1900. But the first mass-produced modern hybrid was the Toyota Prius, introduced in Japan in 1997, followed by the Honda Insight in 1999. Later, improved lithium-ion batteries enabled the modern electric revival, including the Tesla Roadster in 2008 and the Nissan Leaf in 2010. Today the industry is moving toward connected and autonomous vehicles, a topic we will return to in the final section.", "pause": 2}, {"n": 10, "title": "Classification by Energy Source and Engine Position", "start": 1020, "end": 1140, "on": "Petrol | Diesel | LPG/CNG | Hybrid | Battery electric | Engine position: front, rear, mid", "narr": "We will now classify vehicles by their energy source. Petrol, or gasoline, vehicles use spark-ignition engines. Diesel vehicles use compression-ignition engines and are common in trucks and buses because diesel engines are efficient and produce high torque at low speed. Gas vehicles run on compressed natural gas or liquefied petroleum gas, and Nigeria has been promoting compressed natural gas conversion for cost savings. Hybrid vehicles combine an engine with an electric motor and battery. Battery electric vehicles use only a battery and electric motor, and fuel-cell vehicles make electricity from hydrogen. Next, engine position. In a front-engine layout, the engine sits at the front of the car. This is the most common layout because it gives good cooling, a simple structure, and room for passengers and luggage. In a rear-engine layout, the engine is behind the rear axle, as in the Volkswagen Beetle and the Porsche 911. This gives good traction on the driven wheels but can make handling sensitive. In a mid-engine layout, the engine sits between the axles, behind the driver, as in many sports cars. This gives excellent weight balance but limits cabin and luggage space. Why does the layout matter? Because it affects weight distribution, handling, traction, space and cost. A designer chooses the layout to suit the purpose of the vehicle.", "pause": 2}, {"n": 11, "title": "Drive Layouts: FWD, RWD, 4WD and AWD", "start": 1140, "end": 1260, "on": "FWD | RWD | 4WD | AWD", "narr": "The drive layout tells us which wheels receive power. In front-wheel drive, the engine drives the front wheels. It is compact and efficient, because there is no long driveshaft to the rear, and it gives good traction in rain because the engine weight sits over the driven wheels. That is why most small family cars use it. In rear-wheel drive, the engine drives the rear wheels. It gives balanced weight distribution, good acceleration on hills, and is common in trucks, pickups and performance cars. In four-wheel drive, the engine can drive all four wheels through a transfer case, usually with the option to select two-wheel or four-wheel mode and often with low-range gearing for tough terrain. Many Nigerian pickups and SUVs, such as the Toyota Hilux, use this arrangement for rural roads and construction sites. All-wheel drive also powers all four wheels, but it is generally automatic and full time or on demand, using a centre differential or coupling to distribute torque between axles. A quick comparison: front-wheel drive is economical, rear-wheel drive is balanced, four-wheel drive is rugged and all-wheel drive is flexible. Which layout would you choose for a farm road in the rainy season? Think about traction before you answer.", "pause": 3}, {"n": 12, "title": "Body Construction, Chassis and Main Components", "start": 1260, "end": 1380, "on": "Body-on-frame vs unibody | Chassis | Body | Powertrain | Running gear", "narr": "A vehicle can be thought of as four major groups. The chassis is the structural base, which carries the weight and holds everything in position. The body is the passenger and cargo enclosure, including doors, panels and glass. The powertrain consists of the engine, transmission, driveshafts and differential, which create and deliver power. The running gear includes the wheels, tyres, suspension, steering and brakes, which support and control the vehicle on the road. There are two main construction methods. In body-on-frame construction, a strong ladder-type steel frame carries the body, engine and suspension. The body is bolted to the frame. This is very strong and easy to repair, which is why trucks, pickups and many rugged SUVs use it. It is heavier and generally less refined. In unibody, or monocoque, construction, the body and chassis are one welded structure. It is lighter, stiffer, safer in crashes because crumple zones can be designed into it, and used in almost all modern passenger cars. Which is better? It depends on the job. For a car in city traffic, unibody gives comfort and economy. For a vehicle carrying heavy loads on rough roads, body-on-frame gives toughness.", "pause": 2}, {"n": 13, "title": "What an Engine Does", "start": 1380, "end": 1480, "on": "Engine = converts heat energy to mechanical work | SI engine vs CI engine", "narr": "The engine is the heart of the automobile. Its function is to convert the chemical energy stored in fuel into mechanical energy that turns the wheels. It does this in two steps: combustion turns chemical energy into heat and pressure, and the piston and crankshaft convert that into rotation. Automobile engines are mainly of two types. In the spark-ignition engine, usually petrol, a mixture of air and fuel is compressed, and a spark plug ignites it. In the compression-ignition engine, which is the diesel engine, only air is compressed; the compression ratio is higher, typically around fourteen to twenty-three to one, compared with about eight to twelve to one in petrol engines. At the end of compression, fuel is injected, and the high temperature of the compressed air ignites it. Higher compression gives diesel engines better thermal efficiency. Neither engine is perfect. A typical petrol engine converts only about twenty-five to thirty-five percent of fuel energy into useful work. The rest is lost as heat through exhaust and cooling, plus friction. That is why engineers keep improving engines.", "pause": 2}, {"n": 14, "title": "The Four-Stroke Cycle (Part 1: Intake and Compression)", "start": 1480, "end": 1580, "on": "Stroke 1: INTAKE | Stroke 2: COMPRESSION | 4 strokes = 2 crankshaft revolutions", "narr": "Now the most important idea in this lecture: the four-stroke cycle. A stroke is one movement of the piston from top to bottom or bottom to top. The cycle needs four strokes, which equal two complete turns of the crankshaft, and one turn of the camshaft. Stroke one is intake. The intake valve opens, the piston moves down from top dead centre, and the downward motion creates a low pressure in the cylinder. Air, or an air and fuel mixture in port-injected petrol engines, flows in. In diesel and direct-injection petrol engines, only air enters. Stroke two is compression. Both valves are closed. The piston moves up from bottom dead centre, compressing the charge into a very small space, called the combustion chamber. Compression raises the temperature and pressure. In a petrol engine the spark plug fires just before the piston reaches top dead centre. This is called ignition timing, and it ensures peak pressure occurs shortly after the piston begins its downward movement. Pause and think: why must both valves be closed during compression?", "pause": 2}, {"n": 15, "title": "The Four-Stroke Cycle (Part 2: Power and Exhaust)", "start": 1580, "end": 1680, "on": "Stroke 3: POWER | Stroke 4: EXHAUST | Only one stroke produces work", "narr": "Stroke three is the power stroke. Near the end of compression, the spark ignites the mixture. Combustion raises the pressure sharply, pushing the piston down. This is the only stroke that produces useful work; the other three strokes consume a little energy. The piston force is transmitted through the connecting rod to the crankshaft, turning it. Stroke four is exhaust. The exhaust valve opens, and the piston moves up again, pushing burnt gases out through the exhaust port. At the end of the stroke, the exhaust valve closes, the intake valve opens, and the cycle starts again. In real engines the valve timing overlaps. The exhaust valve opens before the power stroke ends, and the intake valve opens before the exhaust stroke finishes, to improve breathing. A single-cylinder engine would run roughly because it has only one power stroke every two revolutions. Therefore multi-cylinder engines are used. A four-cylinder engine has a power stroke every half revolution, giving smoother running, and the firing order is commonly one, three, four, two. Remember the sequence with the phrase: suck, squeeze, bang, blow.", "pause": 2}, {"n": 16, "title": "Main Engine Components", "start": 1680, "end": 1780, "on": "Block | Head | Piston | Rings | Con-rod | Crankshaft | Camshaft | Valves | Spark plug | Injector | Flywheel", "narr": "Let us identify the main components. The cylinder block is the main casting containing the cylinders and passages for coolant and oil. It is made of cast iron or aluminium alloy. The cylinder head sits on top, containing the valves, spark plugs, injectors and combustion chambers. Between them is the head gasket, which seals combustion pressure, coolant and oil. The piston moves up and down inside the cylinder. Piston rings seal against the cylinder wall: compression rings prevent gas leakage and an oil ring scrapes excess oil. The connecting rod links the piston to the crankshaft, and the crankshaft converts the reciprocating motion into rotation. The camshaft has lobes that open the valves at the right time, driven from the crankshaft by a timing belt or chain at half the crankshaft speed. Valves control the gas flow, and a valve spring closes each one. The spark plug ignites the mixture in petrol engines. The fuel injector sprays fuel at a precise time, pressure and quantity. The flywheel, bolted to the crankshaft, stores rotational energy to smooth out the pulses between power strokes, and it carries the ring gear that the starter motor engages.", "pause": 2}, {"n": 17, "title": "Lubrication and Cooling Basics", "start": 1780, "end": 1880, "on": "Lubrication: reduce friction, cool, clean, seal | Cooling: keep about 90°C", "narr": "Inside the engine, metal surfaces slide against each other at high speed. Without lubrication, friction would generate heat and quickly destroy the engine. Engine oil has four jobs: it reduces friction, carries heat away, cleans by carrying contaminants to the filter, and helps seal the piston rings. In most engines an oil pump draws oil from the sump, sends it through a filter, and pumps it under pressure through galleries to the crankshaft, camshaft and other bearings. The oil then drains back to the sump. Viscosity is the thickness of the oil, and ratings such as ten-W-forty describe how it behaves in cold and hot conditions. Wrong oil, or neglected oil changes, is one of the most common reasons engines fail early in our environment, where heat and dust are severe. Cooling is equally important. Only about a third of the fuel energy becomes work. A large share becomes heat. If it is not removed, the engine overheats. In most vehicles, coolant circulates through passages in the block and head, absorbs heat, then flows to the radiator, where air removes it. The normal operating temperature is around ninety degrees Celsius. We will study these systems again in Section 9.", "pause": 2}, {"n": 18, "title": "Engine Performance and Efficiency", "start": 1880, "end": 1980, "on": "Power = torque × angular speed | Efficiency = useful work ÷ fuel energy | Displacement", "narr": "How do we measure engine performance? The key quantities are torque, power and efficiency. Torque is the twisting force the engine produces, measured in newton-metres. It determines how strongly the vehicle accelerates and how well it pulls heavy loads. Power is the rate of doing work, measured in kilowatts or horsepower. Power equals torque multiplied by angular speed, so an engine can have high power by producing high torque or by running at high revolutions per minute. Displacement, or swept volume, is the total volume swept by all the pistons, normally quoted in litres, for example a two-litre engine. Efficiency tells us how well the engine converts fuel energy into useful work. Thermal efficiency is the useful work divided by the fuel energy supplied. Diesel engines are generally more efficient than petrol engines because of higher compression ratio, with modern diesel engines reaching around forty percent or more in best conditions. Turbocharging can increase power from a smaller engine by forcing more air into the cylinders. Here is an engineering application. If two engines have the same power, but one has higher torque at low rpm, which would you prefer for a loaded truck climbing a hill?", "pause": 3}, {"n": 19, "title": "Why a Vehicle Needs a Transmission", "start": 1980, "end": 2076, "on": "Engine → Clutch → Gearbox → Driveshaft → Differential → Axles → Wheels", "narr": "The engine produces useful torque only within a limited speed range, perhaps from one thousand to six thousand revolutions per minute. It also cannot be started under load, and it cannot run backward. Yet a vehicle must start from rest, climb hills, cruise on highways and reverse. The transmission system solves this problem. Its purposes are to connect and disconnect the engine from the wheels, to multiply torque at low vehicle speeds, to allow different speeds while the engine stays in its efficient range, to provide reverse, and to deliver power to the driven wheels. The main parts, in order of power flow, are the clutch or torque converter, the gearbox, the driveshaft in rear-drive layouts, the differential, the axles and the final drive. Think of a bicycle. When you climb a hill, you shift to a low gear. Your legs turn quickly, but the wheel turns slowly with more force. A car gearbox works on exactly the same principle. Low gear gives high torque and low speed, while high gear gives low torque and high speed.", "pause": 2}, {"n": 20, "title": "The Clutch", "start": 2076, "end": 2172, "on": "Flywheel | Clutch disc | Pressure plate | Release bearing", "narr": "The clutch is a friction device that connects and disconnects the engine from the gearbox. It is found in manual transmission vehicles. It has three key parts. The flywheel is attached to the engine crankshaft. The clutch disc, covered with friction material, is mounted on the gearbox input shaft, which has splines, so it can slide along the shaft. The pressure plate, with a diaphragm spring, presses the disc firmly against the flywheel. When your foot is off the pedal, the spring clamps the disc against the flywheel, and engine torque passes through friction to the gearbox. When you press the pedal, a hydraulic or cable linkage pushes the release bearing against the diaphragm spring fingers, which pulls the pressure plate away. The disc is released, and the engine is disconnected so you can change gear or stop without stalling. Starting off requires slip. As you release the pedal, the disc slips briefly against the flywheel, letting the vehicle speed gradually match the engine speed. Excessive slip, such as resting a foot on the pedal or climbing a hill on the clutch, produces heat and wears the friction material, a common cause of clutch failure.", "pause": 2}, {"n": 21, "title": "Manual, Automatic and CVT Gearboxes", "start": 2172, "end": 2268, "on": "Manual: gears + synchromesh | Automatic: torque converter + planetary gears | CVT: belt and cone pulleys", "narr": "In a manual gearbox, gears of different sizes on parallel shafts are selected by the driver using a gear lever and selector forks. Synchromesh rings match the speed of the gear and shaft before engagement, so the shift is smooth and quiet. Manual gearboxes are simple, efficient and relatively cheap, and they remain common in Nigeria. An automatic transmission selects gears by itself. Instead of a clutch, it uses a torque converter and, in a traditional design, planetary gear sets controlled by hydraulically operated clutches and bands. The control system chooses the gear based on vehicle speed and throttle position. Many modern automatics also use electronic control and have six to ten speeds. A continuously variable transmission, or CVT, has no fixed gears. It uses a steel belt or chain running between two variable-diameter pulleys. As the pulley cones move together or apart, the effective diameter changes, giving an infinite number of ratios within a range. This allows the engine to remain near its efficient speed, so CVTs are common in small economical cars. The trade-off is that they can feel different to drive, and are sensitive to poor maintenance.", "pause": 2}, {"n": 22, "title": "Torque Converter, Driveshaft, Differential and Axles", "start": 2268, "end": 2364, "on": "Torque converter: impeller, turbine, stator | Differential | Final drive", "narr": "Let us examine the torque converter. It is a fluid coupling between the engine and automatic gearbox. It has three main elements: the impeller, attached to the engine, the turbine, attached to the gearbox, and the stator, between them. Fluid thrown outward by the impeller strikes the turbine blades and makes the turbine turn. The stator redirects the returning fluid so it helps the impeller, and this gives torque multiplication at low speeds. A lock-up clutch eliminates slip at cruising speed to save fuel. In rear-wheel-drive vehicles, the driveshaft carries power from the gearbox to the rear axle. It has universal joints to allow movement. In front-wheel-drive vehicles, short driveshafts with constant-velocity joints connect the transaxle to the wheels. The differential is crucial. When a car turns a corner, the outer wheel must travel a longer distance than the inner wheel, so the wheels must rotate at different speeds. A differential allows this while still delivering torque to both. Before the differential, the final drive gears, a pinion and crown wheel, provide a last reduction in speed and an increase in torque, and turn the power through ninety degrees in rear-drive layouts. The axle shafts then carry the power to the wheels.", "pause": 2}, {"n": 23, "title": "Power Flow from Engine to Road", "start": 2364, "end": 2460, "on": "Follow the power: Engine → Transmission → Final drive → Wheels → Road", "narr": "Let us now follow the power from the engine to the road. In a rear-wheel-drive manual car, the engine's crankshaft spins the flywheel. With the clutch engaged, power passes to the gearbox input shaft, then through the selected gear pair to the output shaft. The driveshaft carries it to the pinion gear of the rear axle. The pinion turns the crown wheel, which turns the differential and sends power through the axle shafts to the rear wheels. The tyres grip the road, and friction pushes the vehicle forward. In a front-wheel-drive car, the arrangement is shorter. The gearbox and differential are in a single unit called a transaxle, and drive shafts with constant-velocity joints connect the transaxle to the front wheels, allowing the wheels to steer and move up and down. In four-wheel drive, a transfer case splits the power between the front and rear driveshafts. In all-wheel drive, a centre differential or an electronically controlled coupling does the same job. Always remember that the road is the final link. If the tyres cannot grip, because of mud, oil or worn tread, the best powertrain in the world cannot move the vehicle. That connects this section to our next topic.", "pause": 2}, {"n": 24, "title": "Steering System and Rack and Pinion", "start": 2460, "end": 2565, "on": "Steering wheel → Column → Rack and pinion → Tie rods → Steering knuckles", "narr": "The steering system allows the driver to control the direction of the vehicle. When you turn the steering wheel, the motion passes down the steering column, which contains universal joints and, in modern cars, a collapsible design to protect the driver in a crash. The column connects to the steering gear. The most common steering gear in passenger cars is the rack and pinion. A small gear, called the pinion, at the end of the column meshes with a long toothed bar, called the rack. When the pinion rotates, the rack moves left or right. Tie rods at each end of the rack connect to the steering knuckles, which pivot at the wheels and swing the wheels to the desired angle. Rack and pinion is simple, direct and gives good road feel. Heavy vehicles often use a recirculating-ball steering box, because it handles higher loads. The inner and outer wheels must turn at slightly different angles during a corner, because they follow circles of different radius. The geometry that achieves this is called Ackermann geometry. Without it, tyres would scrub and wear unevenly.", "pause": 2}, {"n": 25, "title": "Power Steering", "start": 2565, "end": 2670, "on": "Hydraulic (HPS) | Electro-hydraulic (EHPS) | Electric (EPS)", "narr": "Turning a heavy car at low speed needs high effort, especially when parking. Power steering reduces that effort. Hydraulic power steering uses a pump driven by the engine belt to supply pressurised fluid to a piston attached to the rack. A rotary valve at the pinion directs the fluid to the correct side when the driver turns the wheel. It gives smooth assistance but always draws power from the engine, and leaks can occur from hoses and seals. Electric power steering, or EPS, uses an electric motor on the column or rack to provide assistance. A torque sensor detects how hard the driver is turning, and the control unit decides how much assistance to give based on vehicle speed. It is more energy-efficient because it only uses power when steering. EPS also enables features such as lane-keeping assist and automated parking. Most new cars use it, and electric vehicles need it, since there is no engine belt to drive a pump. If your steering becomes suddenly heavy, a low fluid level, a slipping belt or a failed motor may be the cause. Safe diagnosis begins with those checks.", "pause": 2}, {"n": 26, "title": "Suspension Functions, Springs and Dampers", "start": 2670, "end": 2775, "on": "Suspension: comfort + grip + stability | Springs | Dampers", "narr": "The suspension connects the wheels to the body. It has two major jobs: to isolate occupants from road shocks, which gives comfort, and to keep the tyres in contact with the road, which gives grip, steering control and safety. Road surfaces in many parts of Nigeria test suspension components heavily, so understanding them helps with maintenance. The spring supports the weight of the vehicle and absorbs bumps. Common types are coil springs in passenger cars, leaf springs in trucks and pickups, torsion bars and air springs. But a spring alone would keep bouncing after a bump. So we need a shock absorber, more correctly called a damper. It is a hydraulic cylinder in which a piston forces oil through small orifices, converting the oscillation energy into heat and quickly stopping the bouncing. Worn dampers cause poor braking, wheel hop and long bounce after bumps. A simple test is to push down on a corner of the car and release it. A good damper stops the motion after one or two bounces.", "pause": 2}, {"n": 27, "title": "Control Arms, Ball Joints, Stabilizer Bars and Suspension Types", "start": 2775, "end": 2880, "on": "Control arm | Ball joint | Anti-roll bar | Independent vs dependent", "narr": "The other suspension parts guide the wheel. Control arms, also called wishbones, are hinged links that locate the wheel hub relative to the body while allowing it to move up and down. Ball joints are spherical pivots that connect the control arms to the steering knuckle and allow the wheel to both move up and down and steer. Worn ball joints cause clunking noises and uneven tyre wear, and can be dangerous if they fail. The stabilizer bar, or anti-roll bar, is a torsion bar linking the left and right wheels. When the body leans in a corner, it twists and resists the roll, improving stability. Suspension systems are divided into dependent and independent types. In a dependent system, a solid axle connects both wheels, so a bump on one wheel affects the other. It is strong and simple, so trucks, buses and many pickups use it, usually with leaf springs. In an independent system, each wheel moves separately. Common designs are MacPherson strut and double wishbone, plus multilink at the rear. They give better ride, handling and tyre contact, and most passenger cars use them. Engineering always involves trade-offs. Strength and simplicity favour the solid axle; comfort and handling favour independent suspension.", "pause": 2}, {"n": 28, "title": "Braking and the Hydraulic Principle", "start": 2880, "end": 3000, "on": "Kinetic energy → heat | Pascal's law | Master cylinder → brake lines → callipers", "narr": "The brakes are the most important safety system of the vehicle. Braking converts the kinetic energy of the moving vehicle into heat by friction. Kinetic energy depends on the square of speed, so doubling your speed gives four times the energy to be removed, and roughly four times the braking distance. That is why speeding is so dangerous. Most vehicles use a hydraulic braking system based on Pascal's law: pressure applied to an enclosed fluid is transmitted equally in all directions. When you press the pedal, a pushrod moves a piston in the master cylinder, which pressurises the brake fluid. The fluid flows through brake lines and flexible hoses to the wheel cylinders or calliper pistons, which push the friction material against a rotating disc or drum. Because the calliper pistons have a larger total area than the master cylinder piston, force is multiplied. Most cars also use a vacuum or electric brake booster, so the driver needs less pedal effort. For safety, the master cylinder is a tandem design with two separate circuits, so if one circuit leaks, the other still provides some braking. Brake fluid absorbs moisture over time, which lowers its boiling point, so it should be replaced at intervals recommended by the manufacturer.", "pause": 2}, {"n": 29, "title": "Disc Brakes, Drum Brakes, ABS and EBD", "start": 3000, "end": 3120, "on": "Disc: calliper + pads + rotor | Drum: shoes + wheel cylinder | ABS | EBD", "narr": "A disc brake has a rotor attached to the wheel, a calliper straddling it, and brake pads on either side. Hydraulic pressure pushes the calliper piston, which squeezes the pads against the rotor. Disc brakes dissipate heat well and perform consistently, so they are used on the front wheels of nearly all cars, and often on all four. In a drum brake, a rotating drum surrounds two curved brake shoes. The wheel cylinder pushes the shoes outward against the inside of the drum. Drum brakes are cheaper and work well for parking brakes, so they are still found on rear axles of some vehicles. Now the electronics. If a wheel locks up during hard braking, steering control is lost. The anti-lock braking system, or ABS, uses wheel-speed sensors, a hydraulic modulator and a control unit. When a wheel is about to lock, the system rapidly reduces and restores pressure, many times per second, keeping the wheel turning so the driver can steer. If you feel the pedal pulsing, that is normal. Keep pressing firmly. Electronic brake-force distribution, or EBD, works with ABS. Because weight shifts forward during braking, the rear wheels need less brake force. EBD adjusts the brake force between front and rear wheels. The parking brake uses a cable or an electric actuator to hold the vehicle when stopped.", "pause": 2}, {"n": 30, "title": "Tyres and Road Safety", "start": 3120, "end": 3240, "on": "Tyre size 205/55 R16 | Check pressure monthly | Tread depth: 1.6 mm legal minimum in many countries", "narr": "The tyre is the only part of the vehicle that touches the road, and each contact patch is roughly the size of the palm of your hand. A tyre supports the load, transmits driving and braking forces, steers, and absorbs shocks. A radial tyre has a rubber tread for grip, steel belts under the tread for stability, body plies of fabric cords, sidewalls for flexibility, and beads of steel wire that hold the tyre on the rim. A marking such as two-oh-five, slash, fifty-five, R sixteen tells us the section width in millimetres, the aspect ratio, that is the sidewall height as a percentage of width, the radial construction, and the rim diameter in inches. Other markings give load and speed ratings and the manufacturing date. Tyre pressure matters. Under-inflated tyres overheat, wear at the edges, increase fuel consumption and may burst, especially on hot highways. Over-inflated tyres wear in the centre and reduce grip. Check pressure monthly, when the tyres are cold, using the value on the vehicle placard, not the number on the tyre sidewall. Many legal systems set a minimum tread depth of about one point six millimetres, but wet-weather grip falls well before that. Also, tyres age, so inspect them even if the tread looks fine. Safety is a system. Good tyres, good brakes and a careful driver together prevent accidents.", "pause": 2}, {"n": 31, "title": "Battery, Starter Motor and Alternator", "start": 3240, "end": 3360, "on": "Battery 12 V | Starter motor | Alternator charges at about 13.8 to 14.5 V", "narr": "Let us study how the battery, starter motor and alternator work together. The automobile battery in most cars is a twelve-volt lead-acid battery, made of six cells of about two volts each. A healthy, fully charged battery reads about twelve point six volts at rest. Its main job is to supply the very high current needed to start the engine, and to supply power when the engine is off or when demand is higher than the alternator can provide. When you turn the key or press the start button, a small current energises the starter solenoid. The solenoid does two things: it pushes the starter pinion gear to mesh with the flywheel ring gear, and it closes heavy contacts so battery current flows into the starter motor. The motor turns the engine until it fires. Once the engine runs, a one-way clutch releases the pinion and the solenoid retracts it. The alternator, driven by a belt from the crankshaft, generates alternating current, which internal diodes rectify to direct current. A voltage regulator keeps the system voltage at about thirteen point eight to fourteen point five volts. This supplies the vehicle's electrical loads and recharges the battery. If the battery light comes on while driving, the alternator or its belt is likely at fault.", "pause": 2}, {"n": 32, "title": "Ignition, Lighting, Sensors and Actuators", "start": 3360, "end": 3480, "on": "Ignition coil → spark plug | Sensors → ECU → Actuators", "narr": "The ignition system in a petrol engine provides a high-voltage spark at the right moment. An ignition coil is a transformer that steps twelve volts up to tens of thousands of volts. Modern engines use one coil per cylinder, controlled by the engine computer, and spark plugs with a small gap for the spark to jump across. Diesel engines have no spark plugs, but may use glow plugs to help cold starting. The lighting system includes headlamps, tail lamps, brake lights, indicators and interior lights. Many modern vehicles now use LEDs, which last longer and use less power. Good lighting is a safety feature, especially on dark roads, and so working brake lights and indicators are essential. Modern vehicles are full of sensors and actuators. A sensor measures a physical quantity, such as engine speed, air flow, coolant temperature, throttle position, oxygen in the exhaust or wheel speed. An actuator performs an action, such as an injector opening, a throttle motor moving, or a cooling fan switching on. Sensors send signals to the electronic control unit, which processes them and commands the actuators. This is a closed-loop control system, like a thermostat in a room.", "pause": 2}, {"n": 33, "title": "ECU, Instrument Cluster, Wiring and Diagnostics", "start": 3480, "end": 3600, "on": "ECU | CAN bus | OBD-II port | Fault codes", "narr": "The electronic control unit, or ECU, is the vehicle's computer. It reads inputs from sensors, runs software stored in memory, and controls injectors, ignition, idle speed and other outputs. This is the engine management system. Vehicles often have many control units, for the engine, transmission, ABS, airbags and body functions, connected by a network called the controller area network, or CAN bus, which allows them to share data using only two wires. The instrument cluster is the driver's information display. It shows speed, engine speed, fuel level, temperature and warning lights. Never ignore a red warning light, such as oil pressure or brake failure, and stop safely as soon as possible. Wiring in a vehicle is organised in harnesses, with colour-coded wires, fuses and relays to protect circuits and switch heavy loads. If a fuse blows repeatedly, there is a fault, and replacing it with a bigger fuse is dangerous because it can cause a fire. For diagnostics, modern cars have an on-board diagnostic port, called OBD-II, required on petrol cars in the United States from 1996, with similar systems elsewhere. A scan tool reads diagnostic trouble codes, such as the code for a misfire. A code does not tell you which part to replace; it tells you which circuit or system to investigate.", "pause": 2}, {"n": 34, "title": "Fuel and Air Intake Systems", "start": 3600, "end": 3700, "on": "Tank → Pump → Filter → Rail → Injectors | Air filter → Throttle → Intake manifold", "narr": "An engine needs fuel and air in the correct proportion. For petrol, the ideal chemical ratio is about fourteen point seven parts of air to one part of fuel by mass. The fuel system begins at the fuel tank, which stores the fuel. An electric fuel pump, usually inside the tank, sends fuel under pressure through the fuel filter, which removes dirt and water, to the fuel rail and the injectors. In port injection, injectors spray fuel into the intake port, while in direct injection they spray directly into the cylinder at much higher pressure. Fuel quality is a real issue in many places, so a clogged filter or contaminated fuel can cause hesitation or stalling, and replacing filters on time is good practice. The air intake system filters, measures and controls the air entering the engine. Air passes through the air filter, then the air flow sensor, the throttle body, and the intake manifold to the cylinders. In dusty harmattan conditions, a blocked air filter restricts airflow and increases fuel consumption, so check it regularly. The ECU uses sensor information to adjust the amount of fuel injected.", "pause": 2}, {"n": 35, "title": "Cooling and Lubrication Systems in Detail", "start": 3700, "end": 3800, "on": "Water pump | Thermostat | Radiator | Coolant | Oil pump | Oil filter", "narr": "Let us go deeper into cooling. The water pump, driven by a belt or chain, circulates coolant through the engine. When the engine is cold, the thermostat stays closed, so coolant circulates only inside the engine and warms up quickly. When the coolant reaches the thermostat's opening temperature, typically around eighty-two to ninety-five degrees Celsius, the thermostat opens and coolant flows to the radiator, where air passing through the fins removes heat. An electric fan pulls air through the radiator when the vehicle is slow. The coolant is usually a mixture of water and ethylene glycol antifreeze, with corrosion inhibitors, which raises the boiling point and protects the metals. Never open a hot radiator cap, because pressurised coolant can cause severe burns. For lubrication, the oil pump, usually gear or rotor type, draws oil from the sump through a strainer and pushes it through the oil filter. The filter has a bypass valve so oil still flows if the filter is clogged, and a pressure relief valve protects the system. The oil pressure warning light tells you pressure is low. Change engine oil and filter at the intervals recommended in the owner's manual, and sooner under harsh conditions.", "pause": 2}, {"n": 36, "title": "Exhaust System and Emission Control", "start": 3800, "end": 3900, "on": "Manifold → Catalytic converter → Silencer → Tailpipe | CO, HC, NOx, particulates", "narr": "The exhaust system carries burnt gases away from the engine, reduces noise and cleans the emissions. It begins at the exhaust manifold, which collects gases from each cylinder. Next in many cars is the catalytic converter, then the silencer, also called the muffler, and finally the tailpipe. Combustion produces harmful gases. Carbon monoxide, which is poisonous, results from incomplete burning. Unburnt hydrocarbons contribute to smog. Oxides of nitrogen contribute to smog and acid rain. Diesel engines also produce particulates, the black smoke. Carbon dioxide is not toxic, but it is a greenhouse gas. The three-way catalytic converter in a petrol car contains a ceramic honeycomb coated with precious metals, platinum, palladium and rhodium. It converts carbon monoxide, hydrocarbons and nitrogen oxides into carbon dioxide, water and nitrogen. For it to work, the engine must run near the ideal air-fuel ratio, controlled by oxygen sensors. Leaded petrol destroys catalytic converters, and engine misfires can overheat them. The silencer uses chambers and perforated tubes to cancel sound waves. Diesel vehicles may also use particulate filters. Emission control protects our health and our environment, and removing the catalytic converter, which is sometimes done illegally, is harmful.", "pause": 2}, {"n": 37, "title": "Electric and Hybrid Vehicles", "start": 3900, "end": 4000, "on": "BEV: battery + inverter + motor | Hybrid | BMS | Regenerative braking", "narr": "We now look at modern technology. A battery electric vehicle has a high-voltage battery pack, an inverter that converts direct current to alternating current, and one or more electric motors that drive the wheels through a simple reduction gear. There is no multi-speed gearbox, no exhaust and no engine oil. Electric motors give maximum torque from zero speed, so electric vehicles accelerate strongly and quietly. A hybrid vehicle combines an internal combustion engine, an electric motor and a battery. In a full hybrid, such as the Toyota Prius, the car can move on electric power alone for short distances, and the engine switches on when needed. A plug-in hybrid has a larger battery that can be charged from the grid. The battery management system, or BMS, monitors the voltage, current and temperature of each cell group, balances the cells, protects against overcharge and deep discharge, and estimates the state of charge. This is vital for safety and battery life. Regenerative braking lets the motor act as a generator when you lift off the accelerator or brake, converting kinetic energy back into electrical energy and storing it in the battery. This recovers energy that friction brakes would waste as heat. For Nigeria, key issues for electric vehicles include charging infrastructure and electricity supply. Can you think of other challenges?", "pause": 2}, {"n": 38, "title": "Driver Assistance, Autonomous Driving and Safety Technologies", "start": 4000, "end": 4100, "on": "ADAS: AEB, ACC, lane keeping | SAE Levels 0 to 5 | Airbags, seat belts, crumple zones", "narr": "Advanced driver assistance systems, called ADAS, use cameras, radar and ultrasonic sensors to help the driver. Examples are automatic emergency braking, adaptive cruise control, lane-keeping assistance, blind-spot monitoring and parking assistance. These systems reduce risk, but they assist, they do not replace the driver. Autonomy is described by the Society of Automotive Engineers using six levels, from level zero, no automation, to level five, full automation in all conditions. At level two, the vehicle can steer and control speed, but the driver must monitor constantly. At level three, the system drives in limited conditions and the driver must take over when requested. At levels four and five, the system does not need a human driver within defined areas or everywhere. Research developed strongly after the DARPA Grand Challenge competitions in 2004 and 2005, and companies now operate limited driverless services in selected cities. Passive safety is equally important. Seat belts hold occupants in place. Airbags cushion the impact, and work best with belts. The crumple zones at the front and rear absorb crash energy by deforming, while the rigid passenger cell protects occupants. Remember that the cheapest and most effective safety device is wearing a seat belt.", "pause": 2}, {"n": 39, "title": "Maintenance, the Future and Lecture Summary", "start": 4100, "end": 4200, "on": "Maintain | Innovate | Summary: history → systems → future", "narr": "Before we close, a word about maintenance. A well-maintained vehicle is safer, cheaper to run and more reliable. Follow the service schedule. Check oil, coolant, brake fluid and tyre pressure regularly, and do not ignore warning lights, unusual noises or vibrations. Preventive maintenance costs far less than repairs after a breakdown. The future of automobile engineering is exciting. We will see more electrification, better batteries, connected vehicles that talk to each other and to the road infrastructure, and growing automation. Engineers are also working on lighter materials, alternative fuels, hydrogen and improved recycling. Nigeria has an opportunity too, through local assembly, spare-parts manufacturing, and skills in repair and servicing, building on firms such as Innoson in Nnewi and assembly plants established over the decades. Let us summarise. We began with the definition and classification of automobiles. We traced history from Cugnot's steam carriage, through Benz, Daimler and Maybach, to Ford's assembly line, and on to electric, hybrid and autonomous vehicles. Then we studied the systems: the engine and its four-stroke cycle, the transmission carrying power to the wheels, steering and suspension controlling motion, brakes and tyres ensuring safety, electrical and electronic systems providing control, and the fuel, cooling, lubrication and exhaust systems that keep the engine running cleanly. Thank you for your attention. Review your notes, attempt the practice questions, and I will see you in the next lecture, at the Engr Ero Learning Centre.", "pause": 3}];
const SECTIONS = [
 [1,"Section 1","Introduction to Automobiles"],[4,"Section 2","History and Evolution of the Automobile"],
 [10,"Section 3","Classification and General Construction"],[13,"Section 4","Engine System"],
 [19,"Section 5","Transmission and Drivetrain"],[24,"Section 6","Steering and Suspension"],
 [28,"Section 7","Braking System and Tyres"],[31,"Section 8","Electrical and Electronic Systems"],
 [34,"Section 9","Fuel, Cooling, Lubrication and Exhaust"],[37,"Section 10","Modern Technology and Conclusion"]];
const TOTAL = 4200;
const TIMELINES = {
 4:[["1712","Newcomen: practical atmospheric steam engine"],["1760s-70s","Watt: separate condenser, big efficiency gain"],["1801","Trevithick: steam road carriage, Camborne"]],
 5:[["1769","Cugnot: first small steam vehicle"],["1770-71","Larger fardier a vapeur for artillery"],["~4 km/h","Top speed: a walking pace"],["Today","Preserved in Paris (CNAM museum)"]],
 6:[["1860","Lenoir: commercial gas engine"],["1862","Beau de Rochas describes four-stroke principle"],["1876","Otto builds first successful four-stroke engine"],["1892","Diesel: compression-ignition patent"],["1897","First working diesel engine"]],
 7:[["1885","Benz Patent-Motorwagen built"],["1886","Patent filed 29 January (no. 37435)"],["1888","Bertha Benz: ~100 km, Mannheim to Pforzheim"],["1885-86","Daimler and Maybach: high-speed engine"],["1901","Mercedes 35 hp (Maybach)"],["1926","Daimler-Benz merger"]],
 8:[["1901","Olds: stationary assembly line"],["1908","Ford Model T launched"],["1913","Ford moving assembly line, Highland Park"],["1914","$5 day; chassis in ~93 minutes"],["1927","About 15 million Model Ts built"]],
 9:[["1899","La Jamais Contente passes 100 km/h"],["1900","Lohner-Porsche mixed-drive vehicle"],["1912","Kettering electric self-starter"],["1997","Toyota Prius (Japan)"],["1999","Honda Insight"],["2008","Tesla Roadster"],["2010","Nissan Leaf"]]
};
const $=id=>document.getElementById(id);
const NS="http://www.w3.org/2000/svg";
const fmt=s=>{s=Math.max(0,Math.floor(s));return String(Math.floor(s/60)).padStart(2,"0")+":"+String(s%60).padStart(2,"0")};
let t=0,playing=false,speed=1,voiceOn=true,capOn=true,cur=-1,viz=null,lastSent=-1,audio=null,audioOK=false,secShown=-1;

/* ---------- scene preparation ---------- */
SCENES.forEach(s=>{
  s.dur=s.end-s.start;
  s.items=s.on.split("|").map(x=>x.trim()).filter(Boolean);
  s.sent=s.narr.split(/(?<=[.?!])\s+/).filter(Boolean);
  const speechDur=Math.max(s.dur*0.55,s.dur-s.pause-1.2);
  const chars=s.sent.reduce((a,b)=>a+b.length,0);
  let acc=0.6;s.times=[];
  s.sent.forEach(x=>{s.times.push(acc);acc+=x.length/chars*speechDur});
  s.speechEnd=acc;
  const sec=[...SECTIONS].reverse().find(x=>x[0]<=s.n);s.sec=sec;s.secFirst=sec[0]===s.n;
});

/* ---------- SVG helpers ---------- */
function svgWrap(inner){return `<svg viewBox="0 0 800 480" xmlns="${NS}" font-family="system-ui,Arial,sans-serif">${inner}</svg>`}
function wrapText(s,max){if(s.length<=max)return [s];const w=s.split(" ");if(w.length<2)return [s];let best=1,bd=1e9;for(let i=1;i<w.length;i++){const a=w.slice(0,i).join(" ").length,b=w.slice(i).join(" ").length;const d=Math.abs(a-b);if(d<bd){bd=d;best=i}}return [w.slice(0,best).join(" "),w.slice(best).join(" ")]}

/* ---------- component: four-stroke engine ---------- */
function buildFour(range){
  const r=70,L=170,cx=400,cy=392;
  const html=svgWrap(`
  <defs><radialGradient id="gl"><stop offset="0" stop-color="#ffd27a"/><stop offset="1" stop-color="#ff7a1a" stop-opacity="0"/></radialGradient></defs>
  <rect x="296" y="86" width="208" height="224" rx="4" fill="#16365f" stroke="#4c9bff" stroke-width="3"/>
  <rect id="fill" x="302" y="92" width="196" height="100" fill="#4c9bff" opacity=".5"/>
  <rect x="290" y="52" width="220" height="36" rx="4" fill="#244a7e" stroke="#4c9bff" stroke-width="3"/>
  <rect x="330" y="34" width="12" height="20" fill="#9db3d1"/><rect x="458" y="34" width="12" height="20" fill="#9db3d1"/>
  <rect id="vin" x="321" y="88" width="30" height="6" rx="2" fill="#4c9bff"/><line id="vins" x1="336" y1="40" x2="336" y2="88" stroke="#9db3d1" stroke-width="4"/>
  <rect id="vex" x="449" y="88" width="30" height="6" rx="2" fill="#9aa4b5"/><line id="vexs" x1="464" y1="40" x2="464" y2="88" stroke="#9db3d1" stroke-width="4"/>
  <rect x="394" y="40" width="12" height="46" fill="#cfd8e6"/><circle id="spark" cx="400" cy="100" r="0" fill="url(#gl)"/>
  <text x="336" y="26" text-anchor="middle" font-size="15" fill="#9db3d1">intake valve</text><text x="464" y="26" text-anchor="middle" font-size="15" fill="#9db3d1">exhaust valve</text>
  <path d="M254 70 H330" stroke="#4c9bff" stroke-width="6" stroke-dasharray="3 9" id="airin" opacity="0"/>
  <path d="M470 70 H546" stroke="#8a93a3" stroke-width="6" stroke-dasharray="3 9" id="gasout" opacity="0"/>
  <line id="rod" x1="400" y1="150" x2="400" y2="320" stroke="#cfd8e6" stroke-width="10" stroke-linecap="round"/>
  <rect id="pis" x="302" y="100" width="196" height="58" rx="5" fill="#cfd8e6" stroke="#fff" stroke-width="2"/>
  <line x1="302" y1="112" x2="498" y2="112" stroke="#6b7c95" stroke-width="3" id="ring1"/><line x1="302" y1="122" x2="498" y2="122" stroke="#6b7c95" stroke-width="3" id="ring2"/>
  <circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="#4c9bff" stroke-width="3" stroke-dasharray="6 6"/>
  <circle id="crk" cx="${cx}" cy="${cy-r}" r="14" fill="#ff7a1a"/><circle cx="${cx}" cy="${cy}" r="8" fill="#fff"/>
  <circle id="pin" cx="400" cy="150" r="7" fill="#13335f" stroke="#fff" stroke-width="2"/>
  <text id="stnum" x="24" y="64" font-size="24" font-weight="800" fill="#ff7a1a"></text>
  <text id="stname" x="24" y="102" font-size="30" font-weight="800" fill="#ff7a1a"></text>
  <text id="stsub" x="24" y="146" font-size="17" fill="#eaf1fb"></text>
  <text id="stang" x="24" y="446" font-size="18" fill="#9db3d1"></text>
  ${[0,1,2,3].map(i=>`<g><rect id="pl${i}" x="590" y="${150+i*50}" width="190" height="38" rx="19" fill="#13335f" stroke="#2a5088"/><text x="685" y="${175+i*50}" text-anchor="middle" font-size="17" fill="#eaf1fb">${["1 Intake","2 Compression","3 Power","4 Exhaust"][i]}</text></g>`).join("")}
  `);
  const names=["INTAKE","COMPRESSION","POWER","EXHAUST"];
  const subs=["Piston down, intake valve open: fresh charge enters","Both valves closed, piston up: charge compressed","Spark ignites the charge: gas pressure pushes piston down","Exhaust valve open, piston up: burnt gases leave"];
  const period=range[2];
  return {html,update(local){
    const k=(local%period)/period;let th=range[0]+k*(range[1]-range[0]);th=((th%720)+720)%720;
    const a=th*Math.PI/180,stroke=Math.floor(th/180)%4;
    const px=cx+r*Math.sin(a),py=cy-r*Math.cos(a);
    const pinY=cy-(r*Math.cos(a)+Math.sqrt(L*L-Math.pow(r*Math.sin(a),2)));
    $("crk").setAttribute("cx",px);$("crk").setAttribute("cy",py);
    $("pin").setAttribute("cy",pinY);
    const rod=$("rod");rod.setAttribute("y1",pinY);rod.setAttribute("x2",px);rod.setAttribute("y2",py);
    const top=pinY-46;$("pis").setAttribute("y",top);$("ring1").setAttribute("y1",top+12);$("ring1").setAttribute("y2",top+12);$("ring2").setAttribute("y1",top+22);$("ring2").setAttribute("y2",top+22);
    const f=$("fill");f.setAttribute("height",Math.max(2,top-92));
    const cols=["#4c9bff","#ffb04c","#ff7a1a","#8a93a3"],ops=[.45,.7,.9,.55];
    f.setAttribute("fill",cols[stroke]);f.setAttribute("opacity",ops[stroke]);
    $("vin").setAttribute("y",stroke===0?100:88);$("vins").setAttribute("y2",stroke===0?100:88);
    $("vex").setAttribute("y",stroke===3?100:88);$("vexs").setAttribute("y2",stroke===3?100:88);
    $("vin").setAttribute("fill",stroke===0?"#4c9bff":"#5a6e8c");$("vex").setAttribute("fill",stroke===3?"#c0c7d4":"#5a6e8c");
    const sp=(th>=352&&th<=380)?Math.max(0,30-Math.abs(th-366)*2):0;$("spark").setAttribute("r",sp);
    $("airin").setAttribute("opacity",stroke===0?1:0);$("gasout").setAttribute("opacity",stroke===3?1:0);
    $("airin").setAttribute("stroke-dashoffset",-local*40);$("gasout").setAttribute("stroke-dashoffset",-local*40);
    $("stnum").textContent="STROKE "+(stroke+1)+" OF 4";$("stname").textContent=names[stroke];
    const sb=$("stsub");if(sb.dataset.k!=stroke){sb.dataset.k=stroke;sb.innerHTML="";let line="",ln=0;const mk=l=>{const ts=document.createElementNS(NS,"tspan");ts.setAttribute("x",24);ts.setAttribute("dy",ln?22:0);ts.textContent=l;sb.appendChild(ts);ln++};subs[stroke].split(" ").forEach(w=>{if((line+" "+w).trim().length>26){mk(line);line=w}else line=(line+" "+w).trim()});if(line)mk(line)}
    $("stang").textContent="Crank angle "+String(Math.round(th)).padStart(3," ")+"° of 720°";
    for(let i=0;i<4;i++){const e=$("pl"+i);e.setAttribute("fill",i===stroke?"#ff7a1a":"#13335f");}
  }};
}

/* ---------- component: flow chain ---------- */
function buildFlow(tokens){
  const n=tokens.length;const w=n<=4?160:n===5?132:n===6?112:98,h=n<=5?96:88;
  const gap=n>1?(760-n*w)/(n-1):0;const x0=20,y=190;
  let boxes="";tokens.forEach((tk,i)=>{
    const x=x0+i*(w+gap),ls=wrapText(tk,n<=5?13:10);
    boxes+=`<g id="fb${i}" opacity="0"><rect id="fr${i}" x="${x}" y="${y}" width="${w}" height="${h}" rx="14" fill="#13335f" stroke="#4c9bff" stroke-width="3"/>`+
      ls.map((l,j)=>`<text x="${x+w/2}" y="${y+h/2+(ls.length===1?7:(j?22:-2))}" text-anchor="middle" font-size="${n<=5?19:16}" font-weight="700" fill="#eaf1fb">${l}</text>`).join("")+`<text x="${x+w/2}" y="${y-12}" text-anchor="middle" font-size="15" fill="#9db3d1">${i+1}</text></g>`;
  });
  const xs=x0+w/2,xe=x0+(n-1)*(w+gap)+w/2,ly=y+h+34;
  const html=svgWrap(`<line x1="${xs}" y1="${ly}" x2="${xe}" y2="${ly}" stroke="#2a5088" stroke-width="6" stroke-linecap="round"/>${boxes}<circle id="pulse" cx="${xs}" cy="${ly}" r="11" fill="#ff7a1a"/><text x="400" y="${ly+50}" text-anchor="middle" font-size="18" fill="#9db3d1">Follow the flow from left to right</text>`);
  return {html,update(local){
    const p=(local*0.1)%1,x=xs+p*(xe-xs);$("pulse").setAttribute("cx",x);
    let act=Math.round(p*(n-1));
    for(let i=0;i<n;i++){const g=$("fb"+i);g.setAttribute("opacity",local>i*0.6+0.3?1:0);const r=$("fr"+i);const on=i===act;r.setAttribute("stroke",on?"#ff7a1a":"#4c9bff");r.setAttribute("fill",on?"#2a4f86":"#13335f");}
  }};
}

/* ---------- component: electrical (battery / starter / alternator) ---------- */
function buildElec(){
  const html=svgWrap(`
  <rect x="50" y="170" width="130" height="150" rx="12" fill="#13335f" stroke="#f2b01e" stroke-width="3"/><text x="115" y="238" text-anchor="middle" font-size="22" font-weight="800" fill="#eaf1fb">BATTERY</text><text x="115" y="266" text-anchor="middle" font-size="17" fill="#9db3d1">12 V</text>
  <rect x="320" y="200" width="150" height="110" rx="12" fill="#16365f" stroke="#4c9bff" stroke-width="3"/><text x="395" y="262" text-anchor="middle" font-size="22" font-weight="800" fill="#eaf1fb">ENGINE</text>
  <rect x="580" y="60" width="180" height="100" rx="12" fill="#13335f" stroke="#ff7a1a" stroke-width="3"/><text x="670" y="106" text-anchor="middle" font-size="21" font-weight="800" fill="#eaf1fb">STARTER</text><text x="670" y="132" text-anchor="middle" font-size="16" fill="#9db3d1">motor + solenoid</text>
  <rect x="580" y="330" width="180" height="100" rx="12" fill="#13335f" stroke="#4c9bff" stroke-width="3"/><text x="670" y="376" text-anchor="middle" font-size="21" font-weight="800" fill="#eaf1fb">ALTERNATOR</text><text x="670" y="402" text-anchor="middle" font-size="16" fill="#9db3d1">belt driven</text>
  <path id="pA" d="M180 215 C 300 140, 440 110, 580 110" fill="none" stroke="#2a5088" stroke-width="6"/>
  <path id="pB" d="M580 380 C 440 400, 300 340, 180 285" fill="none" stroke="#2a5088" stroke-width="6"/>
  <line x1="470" y1="255" x2="580" y2="370" stroke="#6f8fb8" stroke-width="4" stroke-dasharray="8 8"/><line x1="470" y1="225" x2="580" y2="135" stroke="#6f8fb8" stroke-width="4" stroke-dasharray="3 6"/>
  <g id="dots">${[0,1,2,3,4].map(i=>`<circle id="d${i}" r="8" fill="#ff3b3b"/>`).join("")}</g>
  <text id="mode" x="40" y="60" font-size="34" font-weight="800" fill="#ff7a1a"></text><text id="msub" x="40" y="94" font-size="19" fill="#eaf1fb"></text>`);
  return {html,update(local){
    const ph=local%12,crank=ph<6,path=$(crank?"pA":"pB"),len=path.getTotalLength();
    $("pA").setAttribute("stroke",crank?"#ff7a1a":"#2a5088");$("pB").setAttribute("stroke",crank?"#2a5088":"#4c9bff");
    for(let i=0;i<5;i++){const p=(((local*0.35)+i/5)%1);const pt=path.getPointAtLength((crank?p:p)*len);const d=$("d"+i);d.setAttribute("cx",pt.x);d.setAttribute("cy",pt.y);d.setAttribute("fill",crank?"#ff3b3b":"#4c9bff")}
    $("mode").textContent=crank?"CRANKING":"CHARGING";
    $("msub").textContent=crank?"Heavy current: battery to starter motor turns the engine":"Alternator (about 13.8 to 14.5 V) runs the loads and recharges the battery";
  }};
}

/* ---------- component: timeline list ---------- */
function buildTimeline(ev){
  const html=`<div style="position:absolute;inset:0;padding:2.2cqw 2.6cqw;display:flex;flex-direction:column;justify-content:center;gap:.9cqw">`+ev.map((e,i)=>`<div id="tl${i}" style="display:flex;align-items:center;gap:1.6cqw;opacity:0;transform:translateY(1cqw);transition:all .5s"><div style="min-width:10cqw;font-size:2.6cqw;font-weight:800;color:#ff7a1a;text-align:right">${e[0]}</div><div style="width:.4cqw;align-self:stretch;background:#2a5088;border-radius:1cqw"></div><div style="font-size:1.75cqw;line-height:1.25">${e[1]}</div></div>`).join("")+`</div>`;
  return {html,update(local,dur){
    ev.forEach((e,i)=>{const on=local>1+i*((dur*0.7)/ev.length);const d=$("tl"+i);if(!d)return;d.style.opacity=on?1:0;d.style.transform=on?"none":"translateY(1cqw)";});
  }};
}

/* ---------- scene entry ---------- */
function chooseViz(s){
  if(s.n===13)return buildFour([0,720,16]);
  if(s.n===14)return buildFour([0,360,7]);
  if(s.n===15)return buildFour([360,720,7]);
  if(s.n===31)return buildElec();
  if(TIMELINES[s.n])return buildTimeline(TIMELINES[s.n]);
  let best=null;
  s.items.forEach(it=>{if(it.includes("→")){let seg=it;if(seg.includes(":"))seg=seg.slice(seg.lastIndexOf(":")+1);const tk=seg.split("→").map(x=>x.trim()).filter(Boolean);if(tk.length>=3&&(!best||tk.length>best.length))best=tk}});
  if(best)return buildFlow(best);
  return null;
}
function enterScene(i){
  cur=i;const s=SCENES[i];lastSent=-1;
  $("title").textContent=s.title;$("secChip").textContent=s.sec[1]+" | "+s.sec[2]+" | Scene "+s.n+" of "+SCENES.length;
  viz=chooseViz(s);const stage=$("stage");
  stage.classList.toggle("cards",!viz);
  $("viz").innerHTML=viz?viz.html:"";
  const on=$("onscreen");on.innerHTML="";s.items.forEach(x=>{const d=document.createElement("div");d.className="c";d.textContent=x;on.appendChild(d)});
  loadImage(s);loadAudio(s);
  const si2=SECTIONS.findIndex(x=>x[0]===s.sec[0]);if($("selChap").selectedIndex!==si2)$("selChap").selectedIndex=si2;
}
function loadImage(s){
  // The supplied package did not include the referenced images/S01...S39 files.
  // Keep the lecture's built-in SVG diagrams visible instead of requesting missing files.
  const v=$("visual"),img=$("img");v.classList.remove("hasimg");img.removeAttribute("src");
}
function loadAudio(s){
  // The supplied package did not include audio/S01...S39.mp3.
  // Browser speech synthesis is enabled by default as the narration fallback.
  if(audio){audio.pause();audio=null}audioOK=false;
}
function syncAudio(force){
  if(!audio||!audioOK)return;const s=SCENES[cur],local=t-s.start;
  audio.playbackRate=Math.min(speed,4);
  if(playing&&local<audio.duration&&speed<=4){if(force||Math.abs(audio.currentTime-local)>0.5)audio.currentTime=local;if(audio.paused)audio.play().catch(()=>{})}
  else audio.pause();
}

/* ---------- voice (fallback when no audio file) ---------- */
function speak(txt){
  if(!("speechSynthesis" in window))return;speechSynthesis.cancel();if(!txt)return;
  const u=new SpeechSynthesisUtterance(txt);u.rate=Math.min(1.05*Math.min(speed,1.6),2);
  const vs=speechSynthesis.getVoices();const v=vs.find(x=>/en-NG/i.test(x.lang))||vs.find(x=>/en-GB/i.test(x.lang))||vs.find(x=>/^en/i.test(x.lang));if(v)u.voice=v;
  speechSynthesis.speak(u);
}

/* ---------- per-frame update ---------- */
function update(){
  let i=SCENES.findIndex(s=>t>=s.start&&t<s.end);if(i<0)i=SCENES.length-1;
  if(i!==cur)enterScene(i);
  const s=SCENES[cur],local=Math.min(t-s.start,s.dur);
  // on-screen chips
  const cs=$("onscreen").children;for(let k=0;k<cs.length;k++){const at=1.2+k*Math.min(6,(s.speechEnd*0.6)/Math.max(1,cs.length));cs[k].classList.toggle("on",local>at)}
  if(viz)viz.update(local,s.dur);
  // captions
  let si=-1;for(let k=0;k<s.times.length;k++){if(local>=s.times[k])si=k}
  const sentEnd=local>s.speechEnd+0.5;
  const cap=$("caption");cap.textContent=(si>=0&&!sentEnd)?s.sent[si]:(sentEnd?"":s.sent[0]&&local>0.6?s.sent[0]:"");
  cap.classList.toggle("off",!capOn||!cap.textContent);
  $("think").classList.toggle("on",sentEnd&&s.pause>0);
  if(si!==lastSent){lastSent=si;if(voiceOn&&playing&&!audioOK&&si>=0&&!sentEnd)speak(s.sent[si])}
  // section card
  const showSec=s.secFirst&&local<3.2;$("seccard").classList.toggle("on",showSec);
  if(showSec)$("seccard").innerHTML=`<small>${s.sec[1].toUpperCase()}</small><b>${s.sec[2]}</b>`;
  // controls
  $("pfill").style.width=(t/TOTAL*100)+"%";$("knob").style.left=(t/TOTAL*100)+"%";
  $("time").textContent=fmt(t)+" / 70:00";
  syncAudio(false);
}
let last=performance.now();
function loop(now){const dt=(now-last)/1000;last=now;if(playing){t+=dt*speed;if(t>=TOTAL){t=TOTAL-0.01;setPlay(false)}update()}requestAnimationFrame(loop)}
function setPlay(p){playing=p;$("bPlay").innerHTML=p?"&#10074;&#10074; Pause":"&#9654; Play";if(!p){if("speechSynthesis" in window)speechSynthesis.cancel();if(audio)audio.pause()}else{lastSent=-1}update()}
function seek(x){t=Math.max(0,Math.min(TOTAL-0.01,x));lastSent=-1;if("speechSynthesis" in window)speechSynthesis.cancel();if(audio)syncAudio(true);update()}
function sceneStart(d){const i=Math.max(0,Math.min(SCENES.length-1,(cur<0?0:cur)+d));seek(SCENES[i].start+0.01)}

/* ---------- wiring ---------- */
$("bPlay").onclick=()=>setPlay(!playing);
$("startcard").onclick=()=>{$("startcard").style.display="none";setPlay(true)};
$("bPrev").onclick=()=>{const s=SCENES[cur];if(t-s.start>3)seek(s.start+0.01);else sceneStart(-1)};
$("bNext").onclick=()=>sceneStart(1);
$("bBack").onclick=()=>seek(t-10);$("bFwd").onclick=()=>seek(t+10);
$("selSpeed").onchange=e=>{speed=parseFloat(e.target.value);syncAudio(true)};
$("bVoice").onclick=()=>{voiceOn=!voiceOn;$("bVoice").textContent="Voice: "+(voiceOn?"on":"off");$("bVoice").classList.toggle("on",voiceOn);if(!voiceOn&&"speechSynthesis" in window)speechSynthesis.cancel();lastSent=-1};
$("bCap").onclick=()=>{capOn=!capOn;$("bCap").classList.toggle("on",capOn);update()};
$("bFull").onclick=()=>{const el=document.documentElement;if(document.fullscreenElement)document.exitFullscreen();else el.requestFullscreen&&el.requestFullscreen()};
const sc=$("seek");
SECTIONS.forEach(sx=>{const s=SCENES.find(z=>z.n===sx[0]);const tk=document.createElement("div");tk.className="tick";tk.style.left=(s.start/TOTAL*100)+"%";sc.appendChild(tk)});
let drag=false;const sk=e=>{const r=sc.getBoundingClientRect();seek((e.clientX-r.left)/r.width*TOTAL)};
sc.addEventListener("pointerdown",e=>{drag=true;sk(e)});window.addEventListener("pointermove",e=>{if(drag)sk(e)});window.addEventListener("pointerup",()=>drag=false);
const sel=$("selChap");SECTIONS.forEach(sx=>{const s=SCENES.find(z=>z.n===sx[0]);const o=document.createElement("option");o.value=s.start;o.textContent=fmt(s.start)+"  "+sx[2];sel.appendChild(o)});
sel.onchange=e=>seek(parseFloat(e.target.value)+0.01);
window.addEventListener("keydown",e=>{if(e.target.tagName==="SELECT")return;
  if(e.code==="Space"){e.preventDefault();$("startcard").style.display="none";setPlay(!playing)}
  else if(e.code==="ArrowRight")seek(t+10);else if(e.code==="ArrowLeft")seek(t-10);else if(e.key==="f")$("bFull").click();else if(e.key==="c")$("bCap").click();});
if("speechSynthesis" in window)speechSynthesis.getVoices();
// allow deep links: index.html#t=1234 (seconds)
const m=location.hash.match(/t=(\d+)/);if(m){t=parseInt(m[1])}
update();requestAnimationFrame(loop);
</script>
</body>
</html>
$engr_ero_html$
)
on conflict (lesson_id) do update set
  title = excluded.title,
  html_content = excluded.html_content,
  updated_at = now();
